import{at as e,it as t,n,vt as r}from"./chunks/framework.CinQa4et.js";var i=JSON.parse(`{"title":"SDKタグと追加連携","description":"","frontmatter":{},"headers":[],"relativePath":"integration/sdk.md","filePath":"integration/sdk.md","lastUpdated":1793671105000}`),a={name:`integration/sdk.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="sdkタグと追加連携" tabindex="-1">SDKタグと追加連携 <a class="header-anchor" href="#sdkタグと追加連携" aria-label="Permalink to “SDKタグと追加連携”">​</a></h1><p>サイト共通タグを1つ設置します。ページごとの商品IDや説明の登録を必須にしません。サイト設定の権限、実装サイトを編集する権限、利用者の同意設計が必要です。</p><h2 id="共通タグ" tabindex="-1">共通タグ <a class="header-anchor" href="#共通タグ" aria-label="Permalink to “共通タグ”">​</a></h2><div class="language-html" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">script</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  defer</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  src</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://YOUR-API-HOST/sdk.js&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-api</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;https://YOUR-API-HOST&quot;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">  data-site</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;YOUR-SITE-ID&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;&lt;/</span><span style="--shiki-light:#11782a;--shiki-dark:#85E89D;">script</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&gt;</span></span></code></pre></div><p><code>defer</code>によりHTMLの解析を妨げずにSDKをダウンロードし、解析完了後に実行します。タグ直後のインラインスクリプトはSDKの実行完了を待たないため、同意APIはSDKの読み込み完了後に呼んでください。</p><p><code>data-site</code>は管理画面のサイトIDと一致させます。APIにはHTTPSのOriginを指定します。ローカル開発のlocalhostだけHTTPを許可します。</p><p>管理画面の「動作確認」に、選択中サイトのタグ例も表示します。APIのJevキーや管理用トークンをタグへ入れないでください。</p><h2 id="同意後に開始する" tabindex="-1">同意後に開始する <a class="header-anchor" href="#同意後に開始する" aria-label="Permalink to “同意後に開始する”">​</a></h2><p>SDKの読み込み完了後、CMP等で同意を取得したときに呼びます。</p><div class="language-js" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">consent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>同意前は観測・通常送信を開始しません。撤回は次です。</p><div class="language-js" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">consent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>撤回時には、このSDKが使うブラウザ内の対象履歴も消去します。</p><p>すでに適切な同意取得が済んでいる場合だけ、タグへ<code>data-consent=&quot;granted&quot;</code>を付ける方法も使えます。単にタグが読み込まれたという理由で同意済みにしないでください。</p><p>読み込み前にAPIを呼ぶと失敗するため、CMPとタグの実行順序を調整します。利用サイトのタグマネージャーやSPAの構成に合わせてください。</p><h2 id="管理画面の設定" tabindex="-1">管理画面の設定 <a class="header-anchor" href="#管理画面の設定" aria-label="Permalink to “管理画面の設定”">​</a></h2><ul><li>オリジンに実サイトのOriginを登録する。</li><li>収集する経路と除外経路を設定する。</li><li>ページ情報を確認し、メタデータ送信を有効にする。</li><li>施策を作り、表示対象パスを設定して配信開始する。</li></ul><p>これらが無効・不一致なら、タグがあっても表示されません。</p><h2 id="任意のイベント・状態" tabindex="-1">任意のイベント・状態 <a class="header-anchor" href="#任意のイベント・状態" aria-label="Permalink to “任意のイベント・状態”">​</a></h2><p>管理画面で登録した名前だけを受け付けます。応募・予約・カート等、ページ閲覧だけではわからない情報に使います。</p><div class="language-js" dir="ltr"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// actionNamesにguide_downloadを登録した場合</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">track</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;guide_download&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// factNamesにregisteredを登録した場合</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;registered&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 登録が完了したら</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">window.JevPersonalization.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">setFact</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;registered&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>イベントの値は省略またはboolean/有限数値、状態はboolean/有限数値です。氏名・メール・フォームの入力値を渡すためのAPIではありません。</p><p>施策の除外factにregisteredを指定した場合、不明な値を「未登録」とみなしません。未完了はfalse、完了はtrueを連携します。</p><h2 id="いつ通信するか" tabindex="-1">いつ通信するか <a class="header-anchor" href="#いつ通信するか" aria-label="Permalink to “いつ通信するか”">​</a></h2><p>同意・サイト設定の読み込み後、収集対象のページごとに、初期の表示判断を1回だけ要求します。現在ページの最低閲覧時間を待ちません。非表示で開いたタブでは、表示されてから要求します。</p><table tabindex="0"><thead><tr><th>きっかけ</th><th>判断APIへの通信</th><th>ブラウザ内の更新</th></tr></thead><tbody><tr><td>初回表示・通常のページ移動</td><td>1回</td><td>現在ページ・流入ページを取得</td></tr><tr><td>SPAのパス変更</td><td>新しいページで1回</td><td>設定を取得し、200ms後に現在ページを取得</td></tr><tr><td>最低閲覧時間に到達</td><td>なし</td><td>有効閲覧履歴へ保存</td></tr><tr><td><code>track()</code>・<code>setFact()</code></td><td>なし</td><td>次のページの初期判断へ引き継ぐ</td></tr><tr><td>メタデータ・クエリだけの変更</td><td>なし</td><td>現在ページの情報を更新</td></tr><tr><td>時間経過・<code>decide()</code>の再実行</td><td>なし</td><td>計測・保存を継続</td></tr></tbody></table><p>通信に失敗した場合や設定の版が古い場合も、同じページで再判定しません。次のページ移動や再読み込みで新しい初期判断を行います。有効閲覧履歴は次のページの判断で使います。APIへ要求しても、配信条件や必要な履歴を満たさなければJevへの問い合わせは行いません。URLの確定条件だけで判定する施策もJevを使いません。</p><h2 id="urlとトラッキングコード" tabindex="-1">URLとトラッキングコード <a class="header-anchor" href="#urlとトラッキングコード" aria-label="Permalink to “URLとトラッキングコード”">​</a></h2><p>現在ページと流入ページ、過去の有効閲覧には、GETパラメータを含むURLを持たせます。「サイト設定 → ページ情報の取得 → 取得しないGETパラメータのキー」で、保存・送信から除きたいキーを1行ずつ指定します。空ならすべてのGETパラメータを保持します。<code>#</code>以降とURL内のユーザー名・パスワードは常に除きます。</p><p>例えば<code>email</code>を除外すると、<code>?cid=mail_runner&amp;email=a%40example.com</code>は<code>?cid=mail_runner</code>になります。除外キーは大文字小文字を区別した完全一致です。URLに検索語や個人情報が入る場合は、対応するキーやページを除外してください。</p><h2 id="spa・cspと確認" tabindex="-1">SPA・CSPと確認 <a class="header-anchor" href="#spa・cspと確認" aria-label="Permalink to “SPA・CSPと確認”">​</a></h2><p>SPAのページ移動やメタデータ変更も観測しますが、対象サイト固有のルーティング・JSON-LD・CMPで確認してください。</p><p>CSPではSDKのスクリプト、APIへの接続、表示画像、必要な独自JavaScriptモジュールの配信元を許可します。実サイトの既存ポリシーに合わせて限定的に設定してください。</p><p>Accessで保護された非公開Previewでは、同一Originの確認用ページだけに認証Cookieの引継ぎを明示します。通常のサイトへの組み込みではこの確認用オプションは不要で、別Originへ認証Cookieを送るものではありません。</p>`,34)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};